def from_roman(s):
    if not isinstance(s, str) or not s:
        raise ValueError('Invalid Roman numeral')
    roman = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        if ch not in roman:
            raise ValueError('Invalid character')
        val = roman[ch]
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    # Validate range and canonical form by converting back? We'll just check no invalid patterns like 'IIII'
    # Simple validation: ensure no more than 3 repeats of I,X,C,M except subtractive combos
    import re
    pattern = r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$'
    if not re.match(pattern, s):
        raise ValueError('Not standard form')
    return total

# Test script
tests = [
    ('III', 3),
    ('IV', 4),
    ('IX', 9),
    ('LVIII', 58),
    ('MCMXCIV', 1994),
]
invalid = ['IIII', 'IC', '', 'VX', 'DM', 'MMMM']
for roman, expected in tests:
    got = from_roman(roman)
    assert got == expected, f'{roman}: expected {expected}, got {got}'
for roman in invalid:
    try:
        from_roman(roman)
        assert False, f'{roman} should raise ValueError'
    except ValueError:
        pass
print('ALL TESTS PASSED')

